local EngravingMachineMaker = {}
local PRODUCTS = {
    simple_wood_engraving = { name = "Preprost leseni gravirni stroj", woodCost = 4, ironCost = 2, brassCost = 1, time = 6, cost = 220, science = 25, happiness = 2, description = "Preprost leseni gravirni stroj za graviranje." },
    iron_reinforced_engraving = { name = "Železnookrepljen gravirni stroj", woodCost = 4, ironCost = 3, brassCost = 1, time = 9, cost = 520, science = 40, happiness = 2, prestige = 2, description = "Železnookrepljen gravirni stroj za trgovce." },
    silver_geared_engraving = { name = "Srebrnozobčan gravirni stroj", woodCost = 4, silverCost = 1, ironCost = 3, brassCost = 1, time = 13, cost = 1200, science = 55, happiness = 3, prestige = 6, description = "Srebrnozobčan gravirni stroj za plemiče." },
    gold_trimmed_engraving = { name = "Zlatookrasni gravirni stroj", woodCost = 4, goldCost = 1, silverCost = 1, ironCost = 3, brassCost = 1, time = 17, cost = 2800, science = 70, happiness = 4, prestige = 14, description = "Zlatookrasni gravirni stroj za visoke plemiče." },
    jewel_set_engraving = { name = "Draguljasta gravirni stroj", woodCost = 4, goldCost = 1, silverCost = 1, ironCost = 3, brassCost = 1, jewelCost = 1, time = 21, cost = 6000, science = 85, happiness = 6, prestige = 27, description = "Gravirni stroj z draguljem za visoko plemstvo." },
    royal_grand_engraving = { name = "Kraljevski veliki gravirni stroj", woodCost = 6, goldCost = 2, silverCost = 2, ironCost = 3, brassCost = 1, jewelCost = 2, pearlCost = 2, time = 28, cost = 13000, science = 95, happiness = 12, prestige = 58, description = "Veliki kraljevski gravirni stroj z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    engraving_workshop = { name = "Gravirna delavnica", cost = { gold = 300, wood = 160, stone = 140, iron = 6, brass = 6 }, upkeep = 7, qualityBonus = 5 },
    printing_loft = { name = "Tiskarska podstrešje", cost = { gold = 1100, wood = 320, stone = 280, silver = 6, brass = 8 }, upkeep = 26, qualityBonus = 18 },
    master_engraving_atelier = { name = "Mojstrski gravirni atelje", cost = { gold = 2900, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 68, qualityBonus = 30 },
    royal_printing_palace = { name = "Kraljevska tiskarska palača", cost = { gold = 12500, wood = 600, stone = 800, gold = 78, jewel = 18 }, upkeep = 250, qualityBonus = 55, prestigeBonus = 50 },
}
EngravingMachineMaker.woodStock = 20; EngravingMachineMaker.ironStock = 14; EngravingMachineMaker.brassStock = 12; EngravingMachineMaker.silverStock = 6; EngravingMachineMaker.goldStock = 6; EngravingMachineMaker.jewelStock = 4; EngravingMachineMaker.pearlStock = 4
EngravingMachineMaker.productStock = {}; EngravingMachineMaker.buildings = {}; EngravingMachineMaker.maker = nil; EngravingMachineMaker.activeMaking = {}; EngravingMachineMaker.totalProducts = 0; EngravingMachineMaker.dayTimer = 0
function EngravingMachineMaker.init() EngravingMachineMaker.woodStock=20; EngravingMachineMaker.ironStock=14; EngravingMachineMaker.brassStock=12; EngravingMachineMaker.silverStock=6; EngravingMachineMaker.goldStock=6; EngravingMachineMaker.jewelStock=4; EngravingMachineMaker.pearlStock=4; EngravingMachineMaker.productStock={}; EngravingMachineMaker.buildings={}; EngravingMachineMaker.maker=nil; EngravingMachineMaker.activeMaking={}; EngravingMachineMaker.totalProducts=0; EngravingMachineMaker.dayTimer=0; print("[EngravingMachineMaker] Royal Engraving Machine Maker System initialized (6 products, 4 buildings)") end
function EngravingMachineMaker.hireMaker(n,s) s=s or math.random(55,90); local c=600+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; EngravingMachineMaker.maker={name=n or ("Gravirar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Gravirar najet: %s (spretnost: %d)",EngravingMachineMaker.maker.name,s),"success") end; return true end
function EngravingMachineMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function EngravingMachineMaker.build(id) local ok,e=EngravingMachineMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(EngravingMachineMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function EngravingMachineMaker.getQualityBonus() local b=0; for _,bd in ipairs(EngravingMachineMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function EngravingMachineMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and EngravingMachineMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ironCost and EngravingMachineMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.brassCost and EngravingMachineMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.silverCost and EngravingMachineMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and EngravingMachineMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and EngravingMachineMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and EngravingMachineMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #EngravingMachineMaker.buildings==0 then return false,"Potrebna gravirna delavnica" end; if not EngravingMachineMaker.maker then return false,"Potreben gravirar" end; return true end
function EngravingMachineMaker.make(pt,qty) qty=qty or 1; local ok,e=EngravingMachineMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then EngravingMachineMaker.woodStock=EngravingMachineMaker.woodStock-d.woodCost*qty end; if d.ironCost then EngravingMachineMaker.ironStock=EngravingMachineMaker.ironStock-d.ironCost*qty end; if d.brassCost then EngravingMachineMaker.brassStock=EngravingMachineMaker.brassStock-d.brassCost*qty end; if d.silverCost then EngravingMachineMaker.silverStock=EngravingMachineMaker.silverStock-d.silverCost*qty end; if d.goldCost then EngravingMachineMaker.goldStock=EngravingMachineMaker.goldStock-d.goldCost*qty end; if d.jewelCost then EngravingMachineMaker.jewelStock=EngravingMachineMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then EngravingMachineMaker.pearlStock=EngravingMachineMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if EngravingMachineMaker.maker then t=math.max(1,t-math.floor(EngravingMachineMaker.maker.skill/13)) end; table.insert(EngravingMachineMaker.activeMaking,{id="engravingmachine_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,science=d.science or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Gradnja: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function EngravingMachineMaker.completeMaking(m) local q=1.0+(EngravingMachineMaker.getQualityBonus()/100); if EngravingMachineMaker.maker then q=q+(EngravingMachineMaker.maker.skill/140) end; q=math.min(2.5,q); EngravingMachineMaker.productStock[m.productType]=(EngravingMachineMaker.productStock[m.productType] or 0)+m.quantity; EngravingMachineMaker.totalProducts=EngravingMachineMaker.totalProducts+m.quantity; if m.science>0 and _G.state then _G.state.science=(_G.state.science or 0)+m.science end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if EngravingMachineMaker.maker then EngravingMachineMaker.maker.itemsMade=EngravingMachineMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then EngravingMachineMaker.maker.skill=math.min(100,EngravingMachineMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Gravirni stroj izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"engravingmachine.completed",{productName=m.productName,science=m.science,prestige=m.prestige,happiness=m.happiness}) end end
function EngravingMachineMaker.update(dt) if not _G.state then return end; EngravingMachineMaker.dayTimer=EngravingMachineMaker.dayTimer+dt; if EngravingMachineMaker.dayTimer>=30 then EngravingMachineMaker.dayTimer=0; for i=#EngravingMachineMaker.activeMaking,1,-1 do local m=EngravingMachineMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then EngravingMachineMaker.completeMaking(m); table.remove(EngravingMachineMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(EngravingMachineMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if EngravingMachineMaker.maker then tu=tu+16 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function EngravingMachineMaker.getStats() return {woodStock=EngravingMachineMaker.woodStock,ironStock=EngravingMachineMaker.ironStock,brassStock=EngravingMachineMaker.brassStock,silverStock=EngravingMachineMaker.silverStock,goldStock=EngravingMachineMaker.goldStock,jewelStock=EngravingMachineMaker.jewelStock,pearlStock=EngravingMachineMaker.pearlStock,productStock=EngravingMachineMaker.productStock,numBuildings=#EngravingMachineMaker.buildings,hasMaker=EngravingMachineMaker.maker~=nil,makerName=EngravingMachineMaker.maker and EngravingMachineMaker.maker.name or "—",makerSkill=EngravingMachineMaker.maker and EngravingMachineMaker.maker.skill or 0,activeMaking=#EngravingMachineMaker.activeMaking,totalProducts=EngravingMachineMaker.totalProducts} end
return EngravingMachineMaker
